css:
  .bulk-drug-page * {
    box-sizing: border-box;
  }

  .bulk-drug-page {
    --bd-primary: #0c4ecb;
    --bd-primary-dark: #083b97;
    --bd-secondary: #12bfd0;
    --bd-text: #183153;
    --bd-text-light: #5e7088;
    --bd-border: #dfe7f1;
    --bd-white: #ffffff;
    --bd-bg-1: #f4f7fc;
    --bd-bg-2: #f7f4ea;
    --bd-bg-3: #eef5df;
    --bd-bg-4: #f3f5f8;
    --bd-bg-5: #f6f1e8;
    --bd-dark: #0d2a52;
    --bd-shadow: 0 14px 40px rgba(11, 40, 92, 0.08);
    --bd-shadow-soft: 0 8px 24px rgba(11, 40, 92, 0.06);
    font-family: Arial, Helvetica, sans-serif;
    color: var(--bd-text);
    background: #fff;
    overflow-x: hidden;
  }

  .bulk-drug-page img {
    max-width: 100%;
    display: block;
  }

  .bulk-drug-page a {
    text-decoration: none;
  }

  .bulk-drug-page .bd-container {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 18px;
  }

  .bulk-drug-page .bd-section {
    padding: 70px 0;
    margin: 0;
  }

  .bulk-drug-page .bd-section-tight {
    padding: 52px 0;
  }

  .bulk-drug-page .bd-bg-light {
    background: var(--bd-bg-1);
  }

  .bulk-drug-page .bd-bg-green {
    background: var(--bd-bg-3);
  }

  .bulk-drug-page .bd-bg-beige {
    background: var(--bd-bg-2);
  }

  .bulk-drug-page .bd-bg-soft {
    background: var(--bd-bg-4);
  }

  .bulk-drug-page .bd-bg-warm {
    background: var(--bd-bg-5);
  }

  .bulk-drug-page h1,
  .bulk-drug-page h2,
  .bulk-drug-page h3,
  .bulk-drug-page h4,
  .bulk-drug-page p {
    margin-top: 0;
  }

  .bulk-drug-page .bd-badge {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .2px;
    color: var(--bd-primary-dark);
    background: #e8f0ff;
    border: 1px solid #d3e1ff;
    padding: 7px 12px;
    border-radius: 999px;
    margin-bottom: 14px;
  }

  .bulk-drug-page .bd-hero {
    background: linear-gradient(90deg, #0b49c2 0%, #0f59d5 55%, #14bfd0 100%);
    padding: 56px 0 32px;
  }

  .bulk-drug-page .bd-hero-grid {
    display: grid;
    grid-template-columns: 1.2fr .82fr;
    gap: 42px;
    align-items: start;
  }

  .bulk-drug-page .bd-hero-content {
    color: #fff;
    padding-top: 18px;
  }

  .bulk-drug-page .bd-hero-content .bd-badge {
    background: rgba(255,255,255,0.14);
    border-color: rgba(255,255,255,0.24);
    color: #fff;
  }

  .bulk-drug-page .bd-hero-content h1 {
    font-size: clamp(32px, 4vw, 52px);
    line-height: 1.08;
    color: #fff;
    font-weight: 800;
    margin-bottom: 14px;
    max-width: 700px;
  }
.bulk-drug-page .aa-section-no-bottom {
    padding-bottom: 0 !important;
}
  .bulk-drug-page .bd-hero-content p {
    color: rgba(255,255,255,.92);
    font-size: 16px;
    line-height: 1.8;
    max-width: 660px;
    margin-bottom: 20px;
  }

  .bulk-drug-page .bd-checks {
    list-style: none;
    padding: 0;
    margin: 0 0 24px;
    display: grid;
    gap: 10px;
  }

  .bulk-drug-page .bd-checks li {
    color: #fff;
    font-size: 14px;
    line-height: 1.5;
    position: relative;
    padding-left: 22px;
  }

  .bulk-drug-page .bd-checks li:before {
    content: "✓";
    position: absolute;
    left: 0;
    top: 0;
    font-weight: 700;
    color: #fff;
  }

  .bulk-drug-page .bd-hero-actions {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
  }

  .bulk-drug-page .bd-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 140px;
    padding: 13px 20px;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 700;
    transition: .25s ease;
  }

  .bulk-drug-page .bd-btn-primary {
    background: #fff;
    color: var(--bd-primary-dark);
  }

  .bulk-drug-page .bd-btn-primary:hover {
    background: #f2f7ff;
  }

  .bulk-drug-page .bd-btn-outline {
    background: transparent;
    color: #fff;
    border: 1px solid rgba(255,255,255,0.35);
  }

  .bulk-drug-page .bd-btn-outline:hover {
    background: rgba(255,255,255,0.08);
  }

  .bulk-drug-page .bd-form-card {
    background: #fff;
    border-radius: 16px;
    padding: 22px;
    box-shadow: 0 18px 48px rgba(10, 34, 83, 0.18);
  }

  .bulk-drug-page .bd-form-card h3 {
    font-size: 24px;
    line-height: 1.2;
    margin-bottom: 18px;
    color: var(--bd-primary-dark);
    font-weight: 800;
  }

  .bulk-drug-page .bd-form-group {
    margin-bottom: 12px;
  }

  .bulk-drug-page .bd-form-group input,
  .bulk-drug-page .bd-form-group textarea,
  .bulk-drug-page .bd-form-group select {
    width: 100%;
    border: 1px solid #d8e2ee;
    border-radius: 8px;
    padding: 12px 12px;
    font-size: 14px;
    color: var(--bd-text);
    outline: none;
    background: #fff;
  }

  .bulk-drug-page .bd-form-group textarea {
    min-height: 88px;
    resize: vertical;
  }

  .bulk-drug-page .bd-form-submit {
    width: 100%;
    border: 0;
    border-radius: 8px;
    padding: 14px 18px;
    background: linear-gradient(90deg, #0d57d5 0%, #14bfd0 100%);
    color: #fff;
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
  }

  .bulk-drug-page .bd-split {
    display: grid;
    grid-template-columns: .95fr 1.05fr;
    gap: 44px;
    align-items: center;
  }

  .bulk-drug-page .bd-split-reverse {
    grid-template-columns: 1.05fr .95fr;
  }

  .bulk-drug-page .bd-image-wrap {
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .bulk-drug-page .bd-image-card {
    max-width: 450px;
  }

  .bulk-drug-page .bd-content h2 {
    font-size: clamp(28px, 3vw, 40px);
    line-height: 1.15;
    margin-bottom: 14px;
    color: var(--bd-primary-dark);
    font-weight: 800;
  }

  .bulk-drug-page .bd-content p {
    color: var(--bd-text-light);
    font-size: 15px;
    line-height: 1.85;
    margin-bottom: 15px;
  }

  .bulk-drug-page .bd-mini-checks {
    list-style: none;
    padding: 0;
    margin: 16px 0 0;
    display: grid;
    gap: 8px;
  }

  .bulk-drug-page .bd-mini-checks li {
    position: relative;
    padding-left: 20px;
    color: var(--bd-text);
    font-size: 14px;
    line-height: 1.6;
  }

  .bulk-drug-page .bd-mini-checks li:before {
    content: "•";
    position: absolute;
    left: 0;
    top: 0;
    color: var(--bd-primary);
    font-weight: 700;
    font-size: 18px;
    line-height: 1;
  }

  .bulk-drug-page .bd-section-head {
    text-align: left;
    margin-bottom: 30px;
  }

  .bulk-drug-page .bd-center-head {
    text-align: center;
    max-width: 860px;
    margin: 0 auto 34px;
  }

  .bulk-drug-page .bd-section-head h2,
  .bulk-drug-page .bd-center-head h2 {
    font-size: clamp(28px, 3vw, 40px);
    line-height: 1.15;
    margin-bottom: 12px;
    color: var(--bd-primary-dark);
    font-weight: 800;
  }

  .bulk-drug-page .bd-section-head p,
  .bulk-drug-page .bd-center-head p {
    font-size: 15px;
    line-height: 1.85;
    color: var(--bd-text-light);
    margin: 0;
  }

  .bulk-drug-page .bd-card-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
  }

  .bulk-drug-page .bd-card {
    background: #fff;
    border: 1px solid #e5ebf3;
    border-radius: 14px;
    padding: 18px;
    box-shadow: var(--bd-shadow-soft);
    height: 100%;
  }

  .bulk-drug-page .bd-card-icon {
    width: 34px;
    height: 34px;
    border-radius: 9px;
    background: #eaf2ff;
    color: var(--bd-primary-dark);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    margin-bottom: 12px;
    font-size: 14px;
  }

  .bulk-drug-page .bd-card h3 {
    font-size: 18px;
    line-height: 1.3;
    color: var(--bd-primary-dark);
    margin-bottom: 8px;
    font-weight: 800;
  }

  .bulk-drug-page .bd-card p {
    margin: 0;
    color: var(--bd-text-light);
    font-size: 14px;
    line-height: 1.75;
  }

  .bulk-drug-page .bd-table-wrap {
    background: #fff;
    border: 1px solid #e3eaf3;
    border-radius: 14px;
    box-shadow: var(--bd-shadow-soft);
    overflow: hidden;
  }

  .bulk-drug-page .bd-table {
    width: 100%;
    border-collapse: collapse;
  }

  .bulk-drug-page .bd-table thead th {
    background: #f2f6fb;
    color: var(--bd-primary-dark);
    font-size: 15px;
    text-align: left;
    padding: 14px 18px;
    font-weight: 700;
    border-bottom: 1px solid #e2e8f0;
  }

  .bulk-drug-page .bd-table tbody td {
    padding: 14px 18px;
    border-bottom: 1px solid #edf1f6;
    font-size: 14px;
    color: var(--bd-text);
    line-height: 1.6;
  }

  .bulk-drug-page .bd-table tbody tr:last-child td {
    border-bottom: 0;
  }

  .bulk-drug-page .bd-report-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px 18px;
  }

  .bulk-drug-page .bd-report-item {
    background: #fff;
    border: 1px solid #e5ebf3;
    border-radius: 12px;
    padding: 16px 18px;
    box-shadow: var(--bd-shadow-soft);
    font-size: 14px;
    line-height: 1.6;
    color: var(--bd-text);
    font-weight: 600;
  }

  .bulk-drug-page .bd-dark-section {
    background: linear-gradient(180deg, #0f315c 0%, #133d72 100%);
    color: #fff;
  }

  .bulk-drug-page .bd-dark-section .bd-center-head h2,
  .bulk-drug-page .bd-dark-section .bd-card h3 {
    color: #fff;
  }

  .bulk-drug-page .bd-dark-section .bd-center-head p,
  .bulk-drug-page .bd-dark-section .bd-card p {
    color: rgba(255,255,255,.82);
  }

  .bulk-drug-page .bd-dark-section .bd-badge {
    background: rgba(255,255,255,.12);
    border-color: rgba(255,255,255,.18);
    color: #fff;
  }

  .bulk-drug-page .bd-dark-section .bd-card {
    background: rgba(255,255,255,.06);
    border-color: rgba(255,255,255,.12);
    box-shadow: none;
  }

  .bulk-drug-page .bd-dark-section .bd-card-icon {
    background: rgba(255,255,255,.14);
    color: #fff;
  }

  .bulk-drug-page .bd-faq-list {
    background: #fff;
    border: 1px solid #e3eaf3;
    border-radius: 16px;
    overflow: hidden;
    box-shadow: var(--bd-shadow-soft);
  }

  .bulk-drug-page .bd-faq-item {
    border-bottom: 1px solid #edf1f6;
    padding: 18px 22px;
  }

  .bulk-drug-page .bd-faq-item:last-child {
    border-bottom: 0;
  }

  .bulk-drug-page .bd-faq-item h3 {
    font-size: 17px;
    color: var(--bd-primary-dark);
    margin-bottom: 8px;
    font-weight: 700;
  }

  .bulk-drug-page .bd-faq-item p {
    margin: 0;
    color: var(--bd-text-light);
    font-size: 14px;
    line-height: 1.8;
  }

  .bulk-drug-page .bd-cta {
    background: linear-gradient(90deg, #0e4fca 0%, #13bfd0 100%);
    text-align: center;
    color: #fff;
  }

  .bulk-drug-page .bd-cta h2 {
    color: #fff;
    font-size: clamp(28px, 3vw, 40px);
    line-height: 1.15;
    margin-bottom: 10px;
    font-weight: 800;
  }

  .bulk-drug-page .bd-cta p {
    max-width: 760px;
    margin: 0 auto 24px;
    color: rgba(255,255,255,.92);
    font-size: 15px;
    line-height: 1.85;
  }

  .bulk-drug-page .bd-footer-space {
    height: 20px;
  }

  @media (max-width: 1100px) {
    .bulk-drug-page .bd-hero-grid,
    .bulk-drug-page .bd-split,
    .bulk-drug-page .bd-split-reverse {
      grid-template-columns: 1fr;
    }

    .bulk-drug-page .bd-card-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 767px) {
    .bulk-drug-page .bd-section {
      padding: 50px 0;
    }

    .bulk-drug-page .bd-hero {
      padding: 38px 0 28px;
    }

    .bulk-drug-page .bd-container {
      padding: 0 14px;
    }

    .bulk-drug-page .bd-card-grid,
    .bulk-drug-page .bd-report-grid {
      grid-template-columns: 1fr;
    }

    .bulk-drug-page .bd-hero-content h1,
    .bulk-drug-page .bd-content h2,
    .bulk-drug-page .bd-section-head h2,
    .bulk-drug-page .bd-center-head h2,
    .bulk-drug-page .bd-cta h2 {
      font-size: 28px;
    }

    .bulk-drug-page .bd-table thead {
      display: none;
    }

    .bulk-drug-page .bd-table,
    .bulk-drug-page .bd-table tbody,
    .bulk-drug-page .bd-table tr,
    .bulk-drug-page .bd-table td {
      display: block;
      width: 100%;
    }

    .bulk-drug-page .bd-table tr {
      border-bottom: 1px solid #edf1f6;
    }

    .bulk-drug-page .bd-table tr:last-child {
      border-bottom: 0;
    }

    .bulk-drug-page .bd-table td {
      padding: 10px 14px;
      border-bottom: 0;
    }
  }
  .aa-error {
    display: block;
    color: red;
    font-size: 12px;
    margin-top: 5px;
}

.success-msg {
    color: green;
    font-size: 14px;
}

.error-msg {
    color: red;
    font-size: 14px;
}
